<?php
declare(strict_types=1);
require __DIR__.'/../src/api.php';
if(!str_ends_with(settings()['db_name'],'_test'))throw new RuntimeException('Disposable _test database required');
function adcCheck(bool $ok,string $message):void {if(!$ok)throw new RuntimeException($message);}
$admin=loadUserAccess(query("SELECT * FROM users WHERE role='admin' AND active=1 AND deleted_at IS NULL ORDER BY id LIMIT 1")[0]);
$tag='admin-control-'.bin2hex(random_bytes(5));$shops=[];$sims=[];$devices=[];$users=[];$records=[];$messages=[];$failed=[];
function adcCase(string $name,callable $fn):void {global $failed;try{$fn();echo "PASS $name\n";}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$failed[]=$name;echo "FAIL $name: ".$e->getMessage()."\n";}}
try {
 $owner=insert('INSERT INTO users(username,password,role) VALUES(?,?,?)',[$tag,password_hash('fixture-password',PASSWORD_DEFAULT),'operator']);$users[]=$owner;
 $shop=aclRoute('POST','/api/shops',['name'=>$tag,'platform'=>'tiktok'],$admin)['id'];$shops[]=$shop;
 $other=aclRoute('POST','/api/shops',['name'=>$tag.'-other','platform'=>'tiktok'],$admin)['id'];$shops[]=$other;
 $sim=insert('INSERT INTO sims(phone,carrier,country,currency,location,shop,shop_id,created_by) VALUES(?,?,?,?,?,?,?,?)',['+639'.random_int(100000000,999999999),'Globe','PH','PHP','fixture',$tag,$shop,$owner]);$sims[]=$sim;
 query('INSERT INTO sim_shops(sim_id,shop_id) VALUES(?,?)',[$sim,$shop]);query('INSERT INTO sim_shops(sim_id,shop_id) VALUES(?,?)',[$sim,$other]);
 $device=insert('INSERT INTO devices(name,token,created_by) VALUES(?,?,?)',[$tag,hash('sha256',$tag),$owner]);$devices[]=$device;
 query('INSERT INTO device_scopes(device_id,shop_id) VALUES(?,?)',[$device,$shop]);query('INSERT INTO user_shops(user_id,shop_id) VALUES(?,?)',[$owner,$shop]);
 $record=insert('INSERT INTO records(sim_id,kind,amount,at,currency_snapshot,shop_id,phone_snapshot,shop_snapshot,owner_id) VALUES(?,?,?,?,?,?,?,?,?)',[$sim,'balances','70.00',microtime(true),'PHP',$shop,query('SELECT phone FROM sims WHERE id=?',[$sim])[0]['phone'],$tag,$owner]);$records[]=$record;
 $message=insert('INSERT INTO messages(device_id,event_id,sim_id,sender,body,received_at,uploaded_at,shop_id,shop_snapshot,owner_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$device,$tag,$sim,'fixture','OTP 123456',microtime(true),microtime(true),$shop,$tag,$owner]);$messages[]=$message;
 $operator=loadUserAccess(query('SELECT * FROM users WHERE id=?',[$owner])[0]);$operator['permissions']=['shops.edit','shops.delete','trash.purge','sims.edit'];
 adcCase('administrator edits platform of a linked shop',function()use($admin,$shop,$tag){aclRoute('PUT','/api/shops/'.$shop,['name'=>$tag,'platform'=>'shopee','platforms'=>['shopee']],$admin);adcCheck(query('SELECT platform FROM shops WHERE id=?',[$shop])[0]['platform']==='shopee','platform not changed');});
 adcCase('operator still cannot change platform of a linked shop',function()use($operator,$shop,$tag){try{aclRoute('PUT','/api/shops/'.$shop,['name'=>$tag,'platform'=>'lazada','platforms'=>['lazada']],$operator);}catch(ApiError $e){adcCheck($e->status===422,'wrong denial');return;}throw new RuntimeException('operator bypassed linked-shop rule');});
 adcCase('administrator can retain multiple shops from one platform',function()use($admin,$shop,$other,$sim){$platform=query('SELECT platform FROM shops WHERE id=?',[$shop])[0]['platform'];query('UPDATE shops SET platform=?,platforms=? WHERE id=?',[$platform,json_encode([$platform]),$other]);simLinkRoute($admin,'PUT','/api/sims/'.$sim.'/shops',['shops'=>[['shop_id'=>$shop],['shop_id'=>$other]]]);adcCheck(count(simShops($sim))===2,'links lost');});
 adcCase('administrator changes number country despite existing ledger',function()use($admin,$sim,$shop,$other){simLinkRoute($admin,'PUT','/api/sims/'.$sim.'/shops',['number'=>['phone'=>'+8613812345678','country'=>'CN','carrier'=>'中国移动','location'=>'中国'],'shops'=>[['shop_id'=>$shop],['shop_id'=>$other]]]);$r=query('SELECT country,currency,balance FROM sims WHERE id=?',[$sim])[0];adcCheck($r['country']==='CN'&&$r['currency']==='CNY'&&$r['balance']===null,'new currency must not reuse an old balance');});
 adcCase('administrator deletes linked shop and detaches it without deleting history',function()use($admin,$shop,$sim,$other,$message,$record,$tag){aclRoute('DELETE','/api/shops/'.$shop,[],$admin);adcCheck(simShopIds($sim)===[$other],'remaining link not preserved');adcCheck((int)query('SELECT shop_id FROM sims WHERE id=?',[$sim])[0]['shop_id']===$other,'primary link not updated');adcCheck(query('SELECT shop_snapshot FROM messages WHERE id=?',[$message])[0]['shop_snapshot']===$tag,'SMS history changed');adcCheck(query('SELECT currency_snapshot FROM records WHERE id=?',[$record])[0]['currency_snapshot']==='PHP','ledger snapshot changed');});
 adcCase('administrator purges referenced shop without orphaned active references',function()use($admin,$shop,$message,$record){query('UPDATE shops SET deleted_at=? WHERE id=?',[microtime(true),$shop]);adcCheck(purgeBlock('shop',$shop,query('SELECT * FROM shops WHERE id=?',[$shop])[0],$admin)===null,'shop purge is blocked');purgeTrashItem($admin,'shop',$shop);adcCheck(!query('SELECT id FROM shops WHERE id=?',[$shop]),'shop still exists');adcCheck(query('SELECT shop_id FROM messages WHERE id=?',[$message])[0]['shop_id']===null,'dangling SMS shop');adcCheck(query('SELECT shop_id FROM records WHERE id=?',[$record])[0]['shop_id']===null,'dangling ledger shop');adcCheck(!query('SELECT shop_id FROM device_scopes WHERE shop_id=?',[$shop]),'dangling device scope');});
 adcCase('purging a shop cannot revive access through old creator ownership',function()use($operator,$message,$record){query('DELETE FROM user_shops WHERE user_id=?',[$operator['id']]);$revoked=$operator;$revoked['shop_ids']=[];foreach(['record'=>$record,'message'=>$message] as $kind=>$id){try{requireDataScope($revoked,$kind,$id);throw new RuntimeException('revoked creator regained '.$kind.' access');}catch(ApiError $e){adcCheck($e->status===404,'unexpected historical access denial');}}});
 adcCase('administrator purges owner account and retains manageable assets',function()use($admin,$owner,$sim,$device){query('UPDATE users SET deleted_at=? WHERE id=?',[microtime(true),$owner]);purgeTrashItem($admin,'user',$owner);adcCheck((int)query('SELECT created_by FROM sims WHERE id=?',[$sim])[0]['created_by']===(int)$admin['id'],'SIM ownership not reassigned');adcCheck((int)query('SELECT created_by FROM devices WHERE id=?',[$device])[0]['created_by']===(int)$admin['id'],'device ownership not reassigned');});
 adcCase('administrator purges bound SIM and refreshes balance after record purge',function()use($admin,$sim,$device,$record){query('INSERT INTO bindings(device_id,subscription_id,sim_id,version) VALUES(?,?,?,?)',[$device,17,$sim,bin2hex(random_bytes(24))]);query('UPDATE records SET deleted_at=? WHERE id=?',[microtime(true),$record]);purgeTrashItem($admin,'record',$record);query('UPDATE sims SET deleted_at=? WHERE id=?',[microtime(true),$sim]);purgeTrashItem($admin,'sim',$sim);adcCheck(!query('SELECT sim_id FROM bindings WHERE sim_id=?',[$sim]),'binding survived SIM purge');});
 adcCase('administrator may delete current login account',function()use($admin,$tag,&$users){$id=insert('INSERT INTO users(username,password,role) VALUES(?,?,?)',[$tag.'-self',password_hash('fixture-password',PASSWORD_DEFAULT),'admin']);$users[]=$id;$self=loadUserAccess(query('SELECT * FROM users WHERE id=?',[$id])[0]);managementRoute('DELETE','/api/admin/users/'.$id,[],$self);adcCheck(query('SELECT deleted_at FROM users WHERE id=?',[$id])[0]['deleted_at']!==null,'self delete was blocked');purgeTrashItem($admin,'user',$id);});
 adcCase('administrator restores a historical record after its SIM was purged',function()use($admin,$tag,&$records){$id=insert('INSERT INTO records(sim_id,kind,amount,at,shop_snapshot,deleted_at) VALUES(NULL,?,?,?,?,?)',['recharges','10.00',microtime(true),$tag,microtime(true)]);$records[]=$id;managementRoute('POST','/api/admin/restore/record/'.$id,[],$admin);adcCheck(query('SELECT deleted_at FROM records WHERE id=?',[$id])[0]['deleted_at']===null,'orphaned history restore blocked');});
 adcCase('administrator purges device even if a legacy binding remains',function()use($admin,$device,$tag,&$sims){$id=insert('INSERT INTO sims(phone,carrier,location,shop) VALUES(?,?,?,?)',['+639'.random_int(100000000,999999999),'Globe','fixture',$tag]);$sims[]=$id;query('INSERT INTO bindings(device_id,subscription_id,sim_id,version) VALUES(?,?,?,?)',[$device,18,$id,bin2hex(random_bytes(24))]);query('UPDATE devices SET deleted_at=? WHERE id=?',[microtime(true),$device]);purgeTrashItem($admin,'device',$device);adcCheck(!query('SELECT device_id FROM bindings WHERE device_id=?',[$device]),'dangling device binding');adcCheck((bool)query('SELECT id FROM sims WHERE id=?',[$id]),'physical SIM was deleted');});
 adcCase('administrator may disable even the final active administrator',function()use($admin,$tag,&$users){$others=query("SELECT id,active FROM users WHERE role='admin'");$id=insert('INSERT INTO users(username,password,role) VALUES(?,?,?)',[$tag.'-last',password_hash('fixture-password',PASSWORD_DEFAULT),'admin']);$users[]=$id;$self=loadUserAccess(query('SELECT * FROM users WHERE id=?',[$id])[0]);try{query("UPDATE users SET active=0 WHERE role='admin' AND id<>?",[$id]);managementRoute('POST','/api/admin/users/'.$id.'/disable',[],$self);adcCheck((int)query('SELECT active FROM users WHERE id=?',[$id])[0]['active']===0,'last admin disable blocked');}finally{foreach($others as $row)query('UPDATE users SET active=? WHERE id=?',[$row['active'],$row['id']]);}});
} finally {
 if(db()->inTransaction())db()->rollBack();
 foreach($messages as $id)query('DELETE FROM messages WHERE id=?',[$id]);foreach($records as $id)query('DELETE FROM records WHERE id=?',[$id]);
 foreach($sims as $id){query('DELETE FROM bindings WHERE sim_id=?',[$id]);query('DELETE FROM sim_shops WHERE sim_id=?',[$id]);query('DELETE FROM sims WHERE id=?',[$id]);}
 foreach($devices as $id){query('DELETE FROM device_scopes WHERE device_id=?',[$id]);query('DELETE FROM devices WHERE id=?',[$id]);}
 foreach($shops as $id){query('DELETE FROM user_shops WHERE shop_id=?',[$id]);query('DELETE FROM device_scopes WHERE shop_id=?',[$id]);query('DELETE FROM shops WHERE id=?',[$id]);}
 foreach($users as $id)query('DELETE FROM users WHERE id=?',[$id]);
}
if($failed)exit(1);
